-- Snapshot of the official 2026 Wellington calendars and the 28 October AGM announcement.
begin;
lock table public.clubs, public.club_programme_settings, public.club_programme,
  public.session_templates, public.session_overrides in share row exclusive mode;
create temporary table wellington_dates(day date, starts time, title text, stream text, kind text,
  playing boolean, source text, series text, round_no integer, primary key(day,title)) on commit drop;
do $import$
declare ids bigint[]; wellington_id bigint;
begin
  select array_agg(distinct c.club_id) into ids from public.clubs c
  left join public.club_programme_settings s using(club_id)
  where lower(trim(c.club_name)) in ('wellington','wellington bridge club','wellington bridge club inc.')
     or s.nz_bridge_club_number=430;
  if cardinality(ids)>1 then raise exception 'Ambiguous Wellington club identity'; end if;
  wellington_id := ids[1];
  if wellington_id is null then
    if pg_get_serial_sequence('public.clubs','club_id') is null then
        select coalesce(max(club_id),0)+1,'Wellington Bridge Club',true from public.clubs
        returning club_id into wellington_id;
    else
        returning club_id into wellington_id;
    end if;
  end if;
  if exists(select from public.club_programme_settings where club_id=wellington_id and nz_bridge_club_number<>430)
    then raise exception 'Conflicting Wellington club number'; end if;
    values(wellington_id,'Wellington Bridge Club',430,'17 Tinakori Road, Thorndon, Wellington 6011','Pacific/Auckland')
    on conflict(club_id) do update set nz_bridge_club_number=coalesce(s.nz_bridge_club_number,430),
      venue=case when trim(s.venue)='' then excluded.venue else s.venue end
      where s.nz_bridge_club_number is null or trim(s.venue)='';
    select wellington_id, 'Grade '||n from generate_series(1,4) n on conflict do nothing;
  -- Published weekly times without individually confirmed dates.
    select wellington_id,p.weekday,p.starts,p.title,p.location,false from (values
      ('Sunday',time '19:00','Casual online bridge','Online'),
      ('Friday',time '19:00','Social online bridge','Online'),
      ('Saturday',time '13:00','Improvers (June–September)','Club')
    ) p(weekday,starts,title,location)
    where not exists(select from public.session_templates t where t.club_id=wellington_id
      and t.day_of_week=p.weekday and t.start_time=p.starts and t.location_type=p.location);
  update public.club_programme_settings set session_legend=jsonb_build_object(
    'title','Wellington programme','entries',(select jsonb_agg(jsonb_build_object(
      'label',v.label,'color',v.color,'match',jsonb_build_object('division',v.label)))
    from (values ('Online · All grades','#2563eb'),('Junior / Intermediate','#0d9488'),
      ('Open','#9333ea'),('Intermediate / Open','#d97706'),('All grades','#16a34a'),
      ('Assisted','#0284c7'),('Special','#be185d'),('Club-wide','#64748b')) v(label,color)))
    where club_id=wellington_id and session_legend is null;

  if exists(select from public.session_templates where club_id=wellington_id and is_current)
    then raise exception 'Reconcile existing Wellington weekly sessions before importing'; end if;
  with dated as (
    select d.*, max(round_no) over(partition by stream,series) as total from wellington_dates d
  ), added as (
      division,series_name,round_number,round_count,partner_search_enabled,confirmation_required,publication_status,notes,source_url)
    select wellington_id, 'wbc-2026:'||day||':'||title,day,title,starts,kind,stream,series,round_no,total,
      playing,starts is null,case when starts is null then 'Start time unconfirmed' else 'Published' end,
      case when starts is null then 'Administrator to confirm start time.' else '' end,
      case when source='announcement' then 'https://wellingtonbridge.co.nz/' else 'https://wellingtonbridge.co.nz/bridge-calendar/' end
    from dated d
    where not exists(select from public.session_overrides o where o.club_id=wellington_id and o.override_date=d.day
      and (o.start_time=d.starts or o.session_name=d.title))
      and not exists(select from public.club_programme p where p.club_id=wellington_id and p.session_date=d.day
      and p.start_time=d.starts and p.division=d.stream)
    on conflict do nothing returning *
  )
    select club_id,null,session_date,'ADD',session_name,start_time,
      case when event_type='Tournament' then 'Tournaments' when division='Online · All grades' then 'Online' else 'Club' end
    from added where partner_search_enabled;
end; $import$;
commit;
